-- #987 wave 1 (pure additions): Kun-Lai Summit creature abilities, imported from DeltaTho PR 15 file 2026_10_25_35_world.sql.
-- 81 creatures, 194 smart_scripts rows. Only creatures that have NO source_type 0 rows today are written here;
-- scripts that would replace existing rows are wave 2. Filters/fixes: see (not shipped)
-- Idempotent: DELETE of the listed entries then INSERT. AIName is set to SmartAI only where AIName and ScriptName are empty.
-- Undo: DELETE FROM smart_scripts WHERE source_type=0 AND FIND_IN_SET(entryorguid, <entries below>); and
--   UPDATE creature_template SET AIName='' WHERE FIND_IN_SET(entry, <entries below>); (entries that already had AIName SmartAI: see backup in (not shipped).

SET @ENTRIES := '59147,59148,59165,59166,59170,59382,59384,59412,59414,59416,59424,59430,59435,59483,59486,59527,59556,59645,59656,59682,59700,59718,59758,59803,59805,59826,59859,59958,59968,59969,59972,60030,60032,60127,60131,60170,60188,60195,60431,60455,60479,60493,60550,60564,60579,60582,60623,60625,60667,60676,60699,60706,60745,60769,60825,60826,60866,60875,61069,61070,61252,61333,61475,61537,61571,61641,61803,61886,62296,63373,63564,63673,63722,63723,64519,64639,64757,65839,65864,65875,66261';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `AIName` = '' AND `ScriptName` = '' AND FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
